param([switch]$NativeX86)
$ErrorActionPreference = 'Stop'
if (!$NativeX86) {
  $powershell32 = Join-Path $env:WINDIR 'SysWOW64/WindowsPowerShell/v1.0/powershell.exe'
  & $powershell32 -NoProfile -File $PSCommandPath -NativeX86
  if ($LASTEXITCODE -ne 0) { throw 'Native x86 DXVK loader check failed' }
  exit 0
}
if ([IntPtr]::Size -ne 4) { throw 'The loader check must run in a 32-bit process' }
Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class BackendLoader {
  [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
  public static extern IntPtr LoadLibraryExW(string path, IntPtr file, uint flags);
  [DllImport("kernel32.dll", CharSet=CharSet.Ansi, ExactSpelling=true)]
  public static extern IntPtr GetProcAddress(IntPtr module, string name);
  [DllImport("kernel32.dll")]
  public static extern bool FreeLibrary(IntPtr module);
}
'@
$repoRoot = Split-Path $PSScriptRoot -Parent
$dll = (Resolve-Path (Join-Path $repoRoot 'dist/l4d2-x86-host-comparison/bin/.l4d2bridge/d3d9vk_x86.dll')).Path
$module = [BackendLoader]::LoadLibraryExW($dll, [IntPtr]::Zero, 0x1100)
if ($module -eq [IntPtr]::Zero) { throw "DXVK LoadLibrary failed: $([Runtime.InteropServices.Marshal]::GetLastWin32Error())" }
try {
  foreach ($name in @('Direct3DCreate9', 'Direct3DCreate9Ex')) {
    if ([BackendLoader]::GetProcAddress($module, $name) -eq [IntPtr]::Zero) { throw "Missing export $name" }
  }
} finally { [void][BackendLoader]::FreeLibrary($module) }
Write-Host 'PASS: official DXVK 2.6.1 x86 DLL loads and exports D3D9 entry points; GPU rendering still requires L4D2 validation.'
